import { MeshBasicNodeMaterial, PlaneGeometry, DoubleSide } from 'three/webgpu';
import { vec3, mix, uv, texture } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // --- STAGE BACKDROP (W-PCP §9: Design Doctrine) ---
  // Create a localized dark gradient backdrop to prevent FLAT_VOID.
  const bgGeom = new PlaneGeometry(8, 6);
  const bgMat = new MeshBasicNodeMaterial({ side: DoubleSide });

  const inkColor = new THREE.Color(colors.ink);
  const surfaceColor = new THREE.Color(colors.surface);

  // Custom TSL vertical gradient
  bgMat.colorNode = mix(
    vec3(inkColor.r, inkColor.g, inkColor.b),
    vec3(surfaceColor.r, surfaceColor.g, surfaceColor.b),
    uv().y
  );

  const backdrop = new THREE.Mesh(bgGeom, bgMat);
  backdrop.position.set(0, 0, -2.0);
  group.add(backdrop);

  // --- BADGE SUBJECT ---
  // Capsule label sizing (W-PCP §9: Spacing rhythm)
  const geom = new PlaneGeometry(1.6, 0.5);
  const mat = new MeshBasicNodeMaterial({ 
    transparent: true,
    side: DoubleSide
  });

  // Base texture loading with fallback to procedural TSL
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.wrapS = THREE.RepeatWrapping;
      tex.wrapT = THREE.RepeatWrapping;
      mat.colorNode = texture(tex);
      mat.needsUpdate = true;
    }).catch(() => {
      // Fallback: procedural metallic grain-ish look
      const surfaceCol = new THREE.Color(colors.surface);
      mat.colorNode = vec3(surfaceCol.r, surfaceCol.g, surfaceCol.b);
    });
  } else {
    const surfaceCol = new THREE.Color(colors.surface);
    mat.colorNode = vec3(surfaceCol.r, surfaceCol.g, surfaceCol.b);
  }

  const badgeMesh = new THREE.Mesh(geom, mat);
  group.add(badgeMesh);

  // --- COMPONENT LEVEL TEXT ---
  // A small Mono-spaced caption on top of the capsule (W-PCP §9: TYPE)
  const textObj = ctx.fontAtlas.createText('COLLECTION', {
    fontSize: 24, // Matches small caption scale
    color: colors.paper,
    align: 'center'
  });
  textObj.position.set(0, -0.05, 0.02);
  group.add(textObj);

  // --- ACCENT EDGE LIGHT (Visual decoration) ---
  const edgeGeom = new PlaneGeometry(1.64, 0.54);
  const edgeMat = new MeshBasicNodeMaterial({
    color: colors.accent,
    side: DoubleSide,
    transparent: true,
    opacity: 0.6
  });
  const edgeMesh = new THREE.Mesh(edgeGeom, edgeMat);
  edgeMesh.position.set(0, 0, -0.01);
  group.add(edgeMesh);

  // --- INTERACTIVITY & ANIMATION ---
  let isHovered = false;
  const hoverTl = gsap.timeline({ paused: true });

  // Hover lift (rise-in subtle) + glow intensification
  hoverTl.to(badgeMesh.position, { z: 0.15, duration: 0.3, ease: 'power2.out' }, 0);
  hoverTl.to(textObj.position, { z: 0.17, duration: 0.3, ease: 'power2.out' }, 0);
  hoverTl.to(edgeMesh.position, { z: 0.05, duration: 0.3, ease: 'power2.out' }, 0);
  hoverTl.to(edgeMat, { opacity: 1.0, duration: 0.3 }, 0);

  // Register Event Handlers on userData (Prism Standard)
  group.userData.handlers = {
    pointerover: () => {
      if (!isHovered) {
        isHovered = true;
        hoverTl.play();
      }
    },
    pointerout: () => {
      if (isHovered) {
        isHovered = false;
        hoverTl.reverse();
      }
    },
    click: () => {
      // Press-down animation feedback
      const clickTl = gsap.timeline();
      clickTl.to([badgeMesh.scale, textObj.scale, edgeMesh.scale], {
        x: 0.95,
        y: 0.95,
        z: 0.95,
        duration: 0.12,
        ease: 'back.out(2)'
      });
      clickTl.to([badgeMesh.scale, textObj.scale, edgeMesh.scale], {
        x: 1.0,
        y: 1.0,
        z: 1.0,
        duration: 0.15,
        ease: 'power2.out'
      });

      // Navigation / UI Event emission
      ctx.emit('hub-collection.select', { id: config.id ?? 'default' });
    }
  };

  // --- CLEANUP ---
  group.userData.cleanup = () => {
    hoverTl.kill();
    geom.dispose();
    mat.dispose();
    edgeGeom.dispose();
    edgeMat.dispose();
    bgGeom.dispose();
    bgMat.dispose();
  };

  return group;
}
